mapper.update:
update mst_bom
   set rev = #{f.rev}, valid_from = #{f.validFrom}, base_qty = #{f.baseQty}, change_no = #{f.changeNo},
       change_reason = #{f.changeReason}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where bom_id = #{id} and status = 'DRAFT' and row_ver = #{f.rowVer}

update mst_bom set status = 'RELEASED', released_at = now(), released_by = #{by},
                   row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where bom_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}


update mst_unit_conv set from_unit = #{fromUnit}, factor = #{factor},
                         to_unit = (select i.unit_cd from mst_item i where i.item_id = #{itemId}),
                         row_ver = row_ver + 1,
                         updated_at = now(), updated_by = #{by}
 where conv_id = #{convId} and item_id = #{itemId} and use_yn = 'Y' and row_ver = #{rowVer}
